import { Component, Input, OnInit, OnDestroy, Output, EventEmitter, ViewChild } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { PartnersService } from '../../../services/partners.service';
import { TranslationService } from '../../../services/translation.service';
import { PartnerEmployee, PartnerEmployeeCreateDto, PartnerEmployeeUpdateDto } from '../../../models/partner.model';
import { Subject, takeUntil } from 'rxjs';
import { ConfirmationModalComponent } from '../../shared/confirmation-modal/confirmation-modal.component';

@Component({
  selector: 'app-partner-employees-modal',
  templateUrl: './partner-employees-modal.component.html',
  styleUrls: ['./partner-employees-modal.component.css'],
  standalone: false
})
export class PartnerEmployeesModalComponent implements OnInit, OnDestroy {
  @Input() partnerId!: number;
  @Input() partnerName!: string;
  @Output() close = new EventEmitter<void>();
  @ViewChild('confirmationModal') confirmationModal!: ConfirmationModalComponent;

  // Modal properties
  isOpen = false;
  isEditMode = false;
  currentEmployeeId: number | null = null;

  // Form
  employeeForm!: FormGroup;

  // Data
  employees: PartnerEmployee[] = [];
  isLoading = false;
  isSubmitting = false;
  employeeToDelete: PartnerEmployee | null = null;

  private destroy$ = new Subject<void>();

  constructor(
    private partnersService: PartnersService,
    private translationService: TranslationService,
    private fb: FormBuilder
  ) {}

  ngOnInit(): void {
    this.initializeForm();
  }

  ngOnDestroy(): void {
    this.destroy$.next();
    this.destroy$.complete();
  }

  private initializeForm(): void {
    this.employeeForm = this.fb.group({
      name: ['', [Validators.required, Validators.minLength(2)]],
      email: ['', [Validators.email]],
      phoneNumber: [''],
      jobTitle: ['']
    });
  }

  openModal(): void {
    this.isOpen = true;
    this.loadEmployees();
  }

  closeModal(): void {
    this.isOpen = false;
    this.resetForm();
    this.employees = [];
    this.close.emit();
  }

  resetForm(): void {
    this.employeeForm.reset();
    this.isEditMode = false;
    this.currentEmployeeId = null;
  }

  loadEmployees(): void {
    if (!this.partnerId) return;

    this.isLoading = true;
    console.log('Loading employees for partner ID:', this.partnerId);
    this.partnersService.getPartnerEmployeesByPartnerId(this.partnerId)
      .pipe(takeUntil(this.destroy$))
      .subscribe({
        next: (response) => {
          console.log('Employees API response:', response);
          if (response && response.success) {
            if (Array.isArray(response.data)) {
              this.employees = response.data;
            } else if (response.data && 'items' in response.data) {
              this.employees = response.data.items;
            } else {
              this.employees = [];
            }
          } else {
            this.employees = [];
          }
          this.isLoading = false;
        },
        error: (error) => {
          console.error('Error loading employees:', error);
          this.employees = [];
          this.isLoading = false;
        }
      });
  }

  addEmployee(): void {
    this.resetForm();
    this.isEditMode = false;
  }

  editEmployee(employee: PartnerEmployee): void {
    this.isEditMode = true;
    this.currentEmployeeId = employee.id;
    
    this.employeeForm.patchValue({
      name: employee.name,
      email: employee.email || '',
      phoneNumber: employee.phoneNumber || '',
      jobTitle: employee.jobTitle || ''
    });
  }

  deleteEmployee(employee: PartnerEmployee): void {
    const confirmData = {
      title: this.translate('common.confirm'),
      message: this.translate('partners.confirm_delete_employee'),
      confirmText: this.translate('common.delete'),
      cancelText: this.translate('common.cancel'),
      type: 'delete' as const
    };
    
    this.confirmationModal.show(confirmData);
    
    // Store the employee to delete for when user confirms
    this.employeeToDelete = employee;
  }

  confirmDelete(): void {
    if (!this.employeeToDelete) return;

    this.partnersService.deletePartnerEmployee(this.employeeToDelete.id)
      .pipe(takeUntil(this.destroy$))
      .subscribe({
        next: (response) => {
          console.log('Delete employee response:', response);
          this.loadEmployees();
          this.showSuccessMessage(this.translate('partners.employee_deleted_successfully') || 'Employee deleted successfully');
          this.employeeToDelete = null;
        },
        error: (error) => {
          console.error('Error deleting employee:', error);
          this.showErrorMessage(this.translate('partners.employee_delete_error') || 'Failed to delete employee');
          this.employeeToDelete = null;
        }
      });
  }

  onSubmit(): void {
    if (this.employeeForm.invalid) {
      this.employeeForm.markAllAsTouched();
      console.log('Form is invalid:', this.employeeForm.errors);
      return;
    }

    this.isSubmitting = true;
    const formValue = this.employeeForm.value;
    console.log('Form submission - isEditMode:', this.isEditMode, 'formValue:', formValue);

    if (this.isEditMode && this.currentEmployeeId) {
      // Update existing employee
      const updateDto: PartnerEmployeeUpdateDto = {
        name: formValue.name,
        email: formValue.email,
        phoneNumber: formValue.phoneNumber,
        jobTitle: formValue.jobTitle
      };

      console.log('Updating employee with data:', updateDto);
      this.partnersService.updatePartnerEmployee(this.currentEmployeeId, updateDto)
        .pipe(takeUntil(this.destroy$))
        .subscribe({
          next: (response) => {
            console.log('Update employee response:', response);
            if (response && response.success) {
              this.loadEmployees();
              this.resetForm();
              this.showSuccessMessage(this.translate('partners.employee_updated_successfully') || 'Employee updated successfully');
            } else {
              this.showErrorMessage(this.translate('partners.employee_update_error') || 'Failed to update employee');
            }
            this.isSubmitting = false;
          },
          error: (error) => {
            console.error('Error updating employee:', error);
            this.isSubmitting = false;
          }
        });
    } else {
      // Create new employee
      const createDto: PartnerEmployeeCreateDto = {
        partnerId: this.partnerId,
        name: formValue.name,
        email: formValue.email,
        phoneNumber: formValue.phoneNumber,
        jobTitle: formValue.jobTitle
      };

      console.log('Creating employee with data:', createDto);
      this.partnersService.createPartnerEmployee(createDto)
        .pipe(takeUntil(this.destroy$))
        .subscribe({
          next: (response) => {
            console.log('Create employee response:', response);
            if (response && response.success) {
              this.loadEmployees();
              this.resetForm();
              this.showSuccessMessage(this.translate('partners.employee_added_successfully') || 'Employee added successfully');
            } else {
              this.showErrorMessage(this.translate('partners.employee_add_error') || 'Failed to add employee');
            }
            this.isSubmitting = false;
          },
          error: (error) => {
            console.error('Error creating employee:', error);
            this.isSubmitting = false;
          }
        });
    }
  }

  translate(key: string): string {
    return this.translationService.translate(key);
  }

  isRTL(): boolean {
    return this.translationService.isRTL();
  }

  showSuccessMessage(message: string) {
    const successData = {
      title: this.translate('common.success'),
      message: message,
      confirmText: this.translate('common.ok'),
      cancelText: '',
      type: 'info' as const
    };
    this.confirmationModal.show(successData);
  }

  showErrorMessage(message: string) {
    const errorData = {
      title: this.translate('common.error'),
      message: message,
      confirmText: this.translate('common.ok'),
      cancelText: '',
      type: 'warning' as const
    };
    this.confirmationModal.show(errorData);
  }
}
