import { HttpClient } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { environment } from '../../environments/environment';
import { Observable } from 'rxjs';
import { map } from 'rxjs/operators';
import { Contact, CreatePartnerDto, Item, PartnerModel, PartnerEmployee, PartnerEmployeeCreateDto, PartnerEmployeeUpdateDto, PartnerEmployeeSearchParams, PartnerEmployeeResponse } from '../models/partner.model';

export interface PartnerSearchParams {
  Search?: string;
  PageSize?: number;
  PageNumber?: number;
  Category?: number;
}

@Injectable({
  providedIn: 'root'
})
export class PartnersService {
  
  private apiUrl=`${environment.apiBaseUrl}/Partners`;
  constructor(private http:HttpClient) { }

  getAllPartners(params: PartnerSearchParams = {}):Observable<PartnerModel>{
    let url = this.apiUrl;
    const queryParams = new URLSearchParams();
    
    if (params.Search) queryParams.append('Search', params.Search);
    if (params.PageSize) queryParams.append('PageSize', params.PageSize.toString());
    if (params.PageNumber) queryParams.append('PageNumber', params.PageNumber.toString());
    if (params.Category !== undefined) queryParams.append('Category', params.Category.toString());
    
    if (queryParams.toString()) {
      url += '?' + queryParams.toString();
    }
    
    return this.http.get<PartnerModel>(url);
  }
  addPartner(partner:CreatePartnerDto):Observable<any>{
    return this.http.post<any>(this.apiUrl,partner);
  }
  updatePartner(id:number,partner:PartnerModel):Observable<any>{
    return this.http.put<any>(`${this.apiUrl}/${id}`,partner);
  }
  getPartner(id:number):Observable<any>{
    return this.http.get<any>(`${this.apiUrl}/${id}`);
  }
  getContacts(partnerId:number):Observable<Contact[]>{
    return this.http.get<any>(`${this.apiUrl}/${partnerId}/contacts`).pipe(
      map(response => response.success ? response.data : [])
    );
  }
  
  addContact(partnerId: number, contact: Contact): Observable<any> {
    return this.http.post<any>(`${this.apiUrl}/${partnerId}/contacts`, contact);
  }

  updateContact(partnerId: number, contactId: number, contact: Contact): Observable<any> {
    return this.http.put<any>(`${this.apiUrl}/${partnerId}/contacts/${contactId}`, contact);
  }
  
  deleteContact(partnerId: number, contactId: number): Observable<any> {
    const url = `${this.apiUrl}/${partnerId}/contacts/${contactId}`;

    return this.http.delete(url, {
      observe: 'response'
    });
  }
  
  deletePartner(id:number){
    return this.http.delete(`${this.apiUrl}/${id}`);
  }
  getPartnerById(id:number):Observable<{success: boolean, message: string, data: Item, errors: any[]}>{
    return this.http.get<{success: boolean, message: string, data: Item, errors: any[]}>(`${this.apiUrl}/${id}`);
  }

  // Partner Employees API methods
  private partnerEmployeesApiUrl = `${environment.apiBaseUrl}/PartnerEmployees`;

  getPartnerEmployees(params: PartnerEmployeeSearchParams = {}): Observable<PartnerEmployeeResponse> {
    let url = this.partnerEmployeesApiUrl;
    const queryParams = new URLSearchParams();
    
    if (params.PartnerId) queryParams.append('PartnerId', params.PartnerId.toString());
    if (params.Search) queryParams.append('Search', params.Search);
    if (params.JobTitle) queryParams.append('JobTitle', params.JobTitle);
    if (params.IsActive !== undefined) queryParams.append('IsActive', params.IsActive.toString());
    if (params.PageSize) queryParams.append('PageSize', params.PageSize.toString());
    if (params.PageNumber) queryParams.append('PageNumber', params.PageNumber.toString());
    
    if (queryParams.toString()) {
      url += '?' + queryParams.toString();
    }
    
    return this.http.get<PartnerEmployeeResponse>(url);
  }

  getPartnerEmployeeById(id: number): Observable<PartnerEmployeeResponse> {
    return this.http.get<PartnerEmployeeResponse>(`${this.partnerEmployeesApiUrl}/${id}`);
  }

  getPartnerEmployeesByPartnerId(partnerId: number): Observable<PartnerEmployeeResponse> {
    const params = new URLSearchParams();
    params.append('PartnerId', partnerId.toString());
    return this.http.get<PartnerEmployeeResponse>(`${this.partnerEmployeesApiUrl}?${params.toString()}`);
  }

  createPartnerEmployee(employee: PartnerEmployeeCreateDto): Observable<PartnerEmployeeResponse> {
    return this.http.post<PartnerEmployeeResponse>(this.partnerEmployeesApiUrl, employee);
  }

  updatePartnerEmployee(id: number, employee: PartnerEmployeeUpdateDto): Observable<PartnerEmployeeResponse> {
    return this.http.put<PartnerEmployeeResponse>(`${this.partnerEmployeesApiUrl}/${id}`, employee);
  }

  deletePartnerEmployee(id: number): Observable<any> {
    return this.http.delete(`${this.partnerEmployeesApiUrl}/${id}`, {
      observe: 'response'
    });
  }
}
