import { AfterViewInit, Component, ElementRef, ViewChild, Output, EventEmitter } from '@angular/core';
import { PartnersService } from '../../../services/partners.service';
import { AbstractControl, FormBuilder, FormGroup, ValidationErrors, Validators, FormArray } from '@angular/forms';
import { TranslationService } from '../../../services/translation.service';
import { PartnersConfirmationModalComponent } from '../partners-confirmation-modal/partners-confirmation-modal.component';
import { CountriesService, Country, City } from '../../../services/countries.service';
import { debounceTime, distinctUntilChanged, switchMap, map } from 'rxjs/operators';
import { Subject, of } from 'rxjs';
import { Contact, PartnerEmployeeCreateDto } from '../../../models/partner.model';
import { PartnerEmployeesModalComponent } from '../partner-employees-modal/partner-employees-modal.component';

@Component({
  selector: 'app-add-partner',
  standalone: false,
  templateUrl: './add-partner.html',
  styleUrl: './add-partner.css'
})
export class AddPartner implements AfterViewInit {
  @ViewChild('confirmationModal') confirmationModal!: PartnersConfirmationModalComponent;
  
  // Custom modal properties
  isOpen = false;
  
  addForm!: FormGroup
  
  // Country and city properties
  countries: Country[] = [];
  filteredCountries: Country[] = [];
  countrySearchTerm: string = '';
  showCountryDropdown = false;
  selectedCountry: Country | null = null;

  filteredCities: City[] = [];
  citySearchTerm: string = '';
  showCityDropdown = false;
  selectedCity: City | null = null;
  private citySearchSubject = new Subject<string>();

  // Loading state
  isSubmitting = false;



  constructor(
    private partnersService: PartnersService,
    private fb: FormBuilder,
    private translationService: TranslationService,
    private countriesService: CountriesService
  ) {}

  ngAfterViewInit(): void {
    // Load countries
    this.loadCountries();
    
    // Setup city search with debounce
    this.citySearchSubject.pipe(
      debounceTime(300),
      distinctUntilChanged(),
      switchMap(searchTerm => {
        if (!searchTerm || searchTerm.length < 1) {
          return of([]);
        }
        // If country is selected, get all cities and filter them
        if (this.selectedCountry) {
          return this.countriesService.getCitiesByCountry(this.selectedCountry.name).pipe(
            map(cities => {
              const term = searchTerm.toLowerCase();
              return cities.filter(city => 
                city.name.toLowerCase().includes(term)
              ).slice(0, 50); // Limit to 50 results
            })
          );
        } else if (searchTerm.length >= 2) {
          // For global search, require at least 2 characters
          return this.countriesService.searchCitiesByName(searchTerm);
        }
        return of([]);
      })
    ).subscribe(cities => {
      this.filteredCities = cities;
      this.showCityDropdown = cities.length > 0;
    });
  }
  
  open() { 
    this.isOpen = true;
    // Reset form when opening
    this.addForm.reset();
  }
  
  close() { 
    this.isOpen = false;
    // Reset form when closing
    this.addForm.reset();
    // Clear contacts and add one default contact
    this.contacts.clear();
    this.addContact();
    // Clear employees
    this.employees.clear();
    this.selectedCountry = null;
    this.selectedCity = null;
    this.countrySearchTerm = '';
    this.citySearchTerm = '';
    this.filteredCountries = this.countries;
    this.filteredCities = [];
    this.showCountryDropdown = false;
    this.showCityDropdown = false;
  }

  // Handle backdrop click
  onBackdropClick(event: Event) {
    if (event.target === event.currentTarget) {
      this.close();
    }
  }

  readonly categories = [
    { key: 0, value: "partners.categories.0" },
    { key: 1, value: "partners.categories.1" },
    { key: 2, value: "partners.categories.2" },
    { key: 3, value: "partners.categories.3" },
    { key: 4, value: "partners.categories.4" },
    { key: 5, value: "partners.categories.5" }
  ]



  ngOnInit() {
    this.initializeForm();
  }

  // Load countries
  loadCountries() {
    this.countriesService.getCountries().subscribe(countries => {
      this.countries = countries;
      this.filteredCountries = countries;
    });
  }

  // Country selection methods
  onCountrySearch(event: any) {
    const searchTerm = event.target.value;
    this.countrySearchTerm = searchTerm;
    
    // Only clear selected country if the search term doesn't match the selected country
    if (this.selectedCountry && searchTerm !== this.selectedCountry.name) {
      this.selectedCountry = null;
    }
    
    this.addForm.patchValue({ country: searchTerm });
    
    if (searchTerm && searchTerm.length >= 2) {
      this.filteredCountries = this.countries.filter(country =>
        country.name.toLowerCase().includes(searchTerm.toLowerCase())
      );
      this.showCountryDropdown = this.filteredCountries.length > 0;
    } else if (searchTerm.length === 0) {
      this.filteredCountries = this.countries;
      this.showCountryDropdown = false;
      this.selectedCountry = null;
    } else {
      this.filteredCountries = this.countries;
      this.showCountryDropdown = true;
    }
  }

  onCountryFocus() {
    this.filteredCountries = this.countries;
    this.showCountryDropdown = true;
  }

  onCountryBlur() {
    setTimeout(() => {
      this.showCountryDropdown = false;
    }, 200);
  }

  selectCountry(country: Country) {
    this.selectedCountry = country;
    this.countrySearchTerm = country.name;
    this.addForm.patchValue({ country: country.name });
    this.filteredCountries = [];
    this.showCountryDropdown = false;
    
    // Clear city when country changes
    this.selectedCity = null;
    this.citySearchTerm = '';
    this.addForm.patchValue({ city: '' });
    this.filteredCities = [];
    this.showCityDropdown = false;
  }

  // City search methods
  onCitySearch(event: any) {
    const searchTerm = event.target.value;
    this.citySearchTerm = searchTerm;
    this.selectedCity = null;
    this.addForm.patchValue({ city: searchTerm });
    
    console.log('City search term:', searchTerm);
    console.log('Selected country:', this.selectedCountry);
    
    if (searchTerm && searchTerm.length >= 1) {
      this.citySearchSubject.next(searchTerm);
    } else if (searchTerm.length === 0 && this.selectedCountry) {
      // If search is cleared and country is selected, show all cities for that country
      this.loadCitiesForCountry();
    } else {
      this.filteredCities = [];
      this.showCityDropdown = false;
    }
  }

  onCityFocus() {
    // When focusing on city field, show cities based on selected country
    if (!this.selectedCountry) {
      // If no country is selected, don't show cities
      this.showCityDropdown = false;
      return;
    }
    
    // If there's a search term with 2+ characters, search with it
    if (this.citySearchTerm && this.citySearchTerm.length >= 2) {
      this.citySearchSubject.next(this.citySearchTerm);
    } else {
      // Otherwise, load all cities for the selected country
      this.loadCitiesForCountry();
    }
  }

  // Load all cities for the selected country
  loadCitiesForCountry() {
    if (!this.selectedCountry) {
      return;
    }
    
    // Use getCitiesByCountry to load all cities for the selected country
    this.countriesService.getCitiesByCountry(this.selectedCountry.name).subscribe(cities => {
      this.filteredCities = cities.slice(0, 50); // Limit to first 50 cities for better performance
      this.showCityDropdown = cities.length > 0;
    });
  }

  onCityBlur() {
    // Delay hiding to allow for click on dropdown items
    setTimeout(() => {
      this.showCityDropdown = false;
    }, 200);
  }

  selectCity(city: City) {
    this.selectedCity = city;
    this.citySearchTerm = city.name;
    this.addForm.patchValue({ city: city.name });
    this.filteredCities = [];
    this.showCityDropdown = false;
  }

  initializeForm() {
    this.addForm = this.fb.group({
      name: ['', [Validators.required, Validators.minLength(3), Validators.maxLength(200)]],
      category: ['', Validators.required],
      sector: ['', [Validators.required, Validators.minLength(2)]],
      country: ['', [Validators.required, Validators.minLength(2)]],
      city: ['', [Validators.required, Validators.minLength(2)]],
      note: [''],
      website: ['', [Validators.required, Validators.minLength(5)]],
      address: ['', [Validators.required, Validators.minLength(5)]],
      contractStartDate: ['', [Validators.required]],
      status: ['', Validators.required],
      internalCoordinatorName: [''],
      internalCoordinatorEmail: ['', [Validators.email]],
      internalCoordinatorPhone: [''],
      internalCoordinatorJobTitle: [''],
      contacts: this.fb.array([]),
      employees: this.fb.array([])
    });
    
    // Add at least one contact by default
    this.addContact();
  }


  // Get contacts FormArray
  get contacts() {
    return this.addForm.get('contacts') as FormArray;
  }

  // Get employees FormArray
  get employees() {
    return this.addForm.get('employees') as FormArray;
  }

  // Add a new contact
  addContact(contact?: Contact) {
    const contactGroup = this.fb.group({
      email: [contact?.email || ''],
      phone: [contact?.phone || ''],
      mobile: [contact?.mobile || '']
    });
    
    this.contacts.push(contactGroup);
  }

  // Remove a contact
  removeContact(index: number) {
    this.contacts.removeAt(index);
  }

  // Add a new employee
  addEmployeeToForm() {
    const employeeGroup = this.fb.group({
      name: ['', [Validators.required, Validators.minLength(2)]],
      email: ['', [Validators.email]],
      phoneNumber: [''],
      jobTitle: ['']
    });
    
    this.employees.push(employeeGroup);
  }

  // Remove an employee
  removeEmployee(index: number) {
    this.employees.removeAt(index);
  }

  isFieldValid(field: string) {
    const control = this.addForm.get(field);
    return control?.touched && control?.invalid
  }

  hasServerError(field: string) {
    const control = this.addForm.get(field);
    return control?.errors?.['serverError'];
  }

  getServerErrorMessage(field: string) {
    const control = this.addForm.get(field);
    return control?.errors?.['serverError'] || '';
  }

  getErrorMessage(field: string) {
    const control = this.addForm.get(field);
    if (!control?.errors) return ''
    
    if (control.errors['required']) {
      return this.translate('common.field_required')
    }
    if (control.errors['minlength']) {
      const requiredLength = control.errors['minlength']['requiredLength']
      if (requiredLength === 2) {
        return this.translate('partners.min_length_2')
      } else if (requiredLength === 3) {
        return this.translate('partners.min_length_3')
      } else if (requiredLength === 5) {
        return this.translate('partners.min_length_5')
      } else if (requiredLength === 10) {
        return this.translate('partners.min_length_10')
      }
      return `Minimum length is ${requiredLength} characters`
    }
    if (control.errors['maxlength']) {
      const requiredLength = control.errors['maxlength']['requiredLength']
      if (requiredLength === 15) {
        return this.translate('partners.max_length_15')
      }
      if (requiredLength === 200) {
        return this.translate('partners.max_length_300')
      }
      return `Maximum length is ${requiredLength} characters`
    }
    if (control.errors['pastDate']) {
      return this.translate('partners.future_date_required')
    }
    return 'Invalid field'
  }

  getContactErrorMessage(control: AbstractControl | null, fieldName: string): string {
    if (!control || !control.errors) return '';
    
    const errors = control.errors;
    if (errors['required']) {
      return this.translate('partners.' + fieldName + '_required');
    }
    if (errors['email']) {
      return this.translate('partners.invalid_email');
    }
    if (errors['minlength']) {
      return this.translate('partners.min_length_5');
    }
    return '';
  }

  getEmployeeErrorMessage(control: AbstractControl | null, fieldName: string): string {
    if (!control || !control.errors) return '';
    
    const errors = control.errors;
    if (errors['required']) {
      return this.translate('common.field_required');
    }
    if (errors['email']) {
      return this.translate('partners.invalid_email');
    }
    if (errors['minlength']) {
      return this.translate('partners.min_length_2');
    }
    return '';
  }

  onSubmit() {
    if (this.addForm.invalid) {
      this.addForm.markAllAsTouched()
      return
    }

    this.isSubmitting = true;
    const formValue = this.addForm.value;
    
    // Ensure all required fields are included and properly formatted
    const partnerData = {
      name: formValue.name,
      category: parseInt(formValue.category),
      sector: formValue.sector,
      country: formValue.country,
      city: formValue.city,
      note: formValue.note,
      website: formValue.website,
      address: formValue.address,
      contractStartDate: new Date(formValue.contractStartDate).toISOString(),
      status: parseInt(formValue.status),
      internalCoordinatorName: formValue.internalCoordinatorName || undefined,
      internalCoordinatorEmail: formValue.internalCoordinatorEmail || undefined,
      internalCoordinatorPhone: formValue.internalCoordinatorPhone || undefined,
      internalCoordinatorJobTitle: formValue.internalCoordinatorJobTitle || undefined
    };

    console.log('Submitting partner data:', partnerData);

    this.partnersService.addPartner(partnerData).subscribe({
      next: (res) => {
        console.log('Partner created successfully:', res);
        
        // Get the created partner ID from response
        const partnerId = res.data?.id || res.id;
        
        // Create contacts and employees for the new partner
        if (partnerId) {
          const hasContacts = formValue.contacts && formValue.contacts.length > 0;
          const hasEmployees = formValue.employees && formValue.employees.length > 0;
          
          if (hasContacts || hasEmployees) {
            this.createContactsAndEmployees(partnerId, formValue.contacts || [], formValue.employees || []);
          } else {
            this.isSubmitting = false;
            this.showSuccessMessage(this.translate('partners.created_success'));
            this.close();
            setTimeout(() => {
              window.location.reload();
            }, 1500);
          }
        } else {
          this.isSubmitting = false;
          this.showSuccessMessage(this.translate('partners.created_success'));
        }
      },
      error: (error) => {
        console.error('Error creating partner:', error);
        this.isSubmitting = false;
        this.handleApiErrors(error);
      }
    })
  }

  private createContactsAndEmployees(partnerId: number, contacts: any[], employees: any[]) {
    const validContacts = contacts.filter(contact => 
      contact.email && contact.phone && contact.mobile
    );
    
    const validEmployees = employees.filter(employee => 
      employee.name && employee.name.trim().length >= 2
    );

    const totalOperations = validContacts.length + validEmployees.length;
    
    if (totalOperations === 0) {
      this.isSubmitting = false;
      this.showSuccessMessage(this.translate('partners.created_success'));
      return;
    }

    let completedOperations = 0;
    let hasError = false;

    // Create contacts
    validContacts.forEach((contact, index) => {
      this.partnersService.addContact(partnerId, contact).subscribe({
        next: (res) => {
          console.log(`Contact ${index + 1} created successfully:`, res);
          completedOperations++;
          
          if (completedOperations === totalOperations && !hasError) {
            this.isSubmitting = false;
            this.showSuccessMessage(this.translate('partners.created_success'));
            this.close();
            setTimeout(() => {
              window.location.reload();
            }, 1500);
          }
        },
        error: (error) => {
          console.error(`Error creating contact ${index + 1}:`, error);
          hasError = true;
          this.isSubmitting = false;
          this.handleApiErrors(error);
        }
      });
    });

    // Create employees
    validEmployees.forEach((employee, index) => {
      const employeeDto: PartnerEmployeeCreateDto = {
        partnerId: partnerId,
        name: employee.name,
        email: employee.email || '',
        phoneNumber: employee.phoneNumber || '',
        jobTitle: employee.jobTitle || ''
      };

      this.partnersService.createPartnerEmployee(employeeDto).subscribe({
        next: (res) => {
          console.log(`Employee ${index + 1} created successfully:`, res);
          completedOperations++;
          
          if (completedOperations === totalOperations && !hasError) {
            this.isSubmitting = false;
            this.showSuccessMessage(this.translate('partners.created_success'));
            this.close();
            setTimeout(() => {
              window.location.reload();
            }, 1500);
          }
        },
        error: (error) => {
          console.error(`Error creating employee ${index + 1}:`, error);
          hasError = true;
          this.isSubmitting = false;
          this.handleApiErrors(error);
        }
      });
    });
  }

  private handleApiErrors(error: any) {
    if (error.error?.errors) {
      // Handle validation errors by setting them on form controls
      const errors = error.error.errors;
      
      Object.keys(errors).forEach(fieldName => {
        const control = this.addForm.get(this.getFormFieldName(fieldName));
        if (control) {
          control.setErrors({ serverError: errors[fieldName][0] });
          control.markAsTouched();
        }
      });
    } else {
      // Show generic error in alert
      let errorMessage = 'Unknown error occurred';
      if (error.error?.message) {
        errorMessage = error.error.message;
      } else if (error.message) {
        errorMessage = error.message;
      }
      this.showErrorMessage(this.translationService.translate('common.error') + ': ' + errorMessage);
    }
  }

  private getFormFieldName(apiFieldName: string): string {
    // Map API field names (capitalized) to form field names (lowercase)
    const fieldMapping: { [key: string]: string } = {
      'Name': 'name',
      'Category': 'category',
      'Sector': 'sector',
      'Country': 'country',
      'City': 'city',
      'Note': 'note',
      'Website': 'website',
      'Address': 'address',
      'ContractStartDate': 'contractStartDate',
      'Status': 'status',
      'InternalCoordinatorName': 'internalCoordinatorName',
      'InternalCoordinatorEmail': 'internalCoordinatorEmail',
      'InternalCoordinatorPhone': 'internalCoordinatorPhone',
      'InternalCoordinatorJobTitle': 'internalCoordinatorJobTitle'
    };
    return fieldMapping[apiFieldName] || apiFieldName.toLowerCase();
  }

  translate(key: string): string {
    return this.translationService.translate(key);
  }

  isRTL(): boolean {
    return this.translationService.isRTL();
  }

  showSuccessMessage(message: string) {
    const successData = {
      title: this.translate('common.success'),
      message: message,
      confirmText: this.translate('common.ok'),
      cancelText: '',
      type: 'info' as const
    };
    this.confirmationModal.show(successData);
  }

  showErrorMessage(message: string) {
    const errorData = {
      title: this.translate('common.error'),
      message: message,
      confirmText: this.translate('common.ok'),
      cancelText: '',
      type: 'warning' as const
    };
    this.confirmationModal.show(errorData);
  }

}
